def gamestate(board):
    # Validate board structure: should be 3x3
    if not isinstance(board, (list, tuple)) or len(board) != 3:
        raise ValueError("Invalid board: must be a 3x3 grid")
    grid = []
    for i, row in enumerate(board):
        if not isinstance(row, (list, tuple, str)) or len(row) != 3:
            raise ValueError("Invalid board: must be a 3x3 grid")
        # convert row to list of characters if it's a string
        if isinstance(row, str):
            row_cells = list(row)
        else:
            row_cells = list(row)
        grid.append(row_cells)

    # Validate characters and count X/O/empty
    valid = {'X', 'O', ' '}
    count_x = count_o = count_empty = 0
    for r in range(3):
        for c in range(3):
            cell = grid[r][c]
            if cell not in valid:
                raise ValueError(f"Invalid board: unexpected character '{cell}'")
            if cell == 'X':
                count_x += 1
            elif cell == 'O':
                count_o += 1
            else:
                count_empty += 1

    # Check basic turn order by counts
    if count_o > count_x:
        raise ValueError("Wrong turn order: O started")
    if count_x - count_o > 1:
        raise ValueError("Wrong turn order: X went twice")

    # Helper to check lines
    def three_in_line(a, b, c):
        return a == b == c and a in ('X', 'O')

    winners = set()
    # rows
    for r in range(3):
        if three_in_line(grid[r][0], grid[r][1], grid[r][2]):
            winners.add(grid[r][0])
    # cols
    for c in range(3):
        if three_in_line(grid[0][c], grid[1][c], grid[2][c]):
            winners.add(grid[0][c])
    # diagonals
    if three_in_line(grid[0][0], grid[1][1], grid[2][2]):
        winners.add(grid[0][0])
    if three_in_line(grid[0][2], grid[1][1], grid[2][0]):
        winners.add(grid[0][2])

    # If both players have winning lines -> impossible (game should have ended)
    if 'X' in winners and 'O' in winners:
        raise ValueError("Impossible board: game should have ended after the game was won")

    # Single winner: validate counts consistent with who moved last
    if 'X' in winners:
        # X must have played last, so X count must be one greater than O
        if count_x != count_o + 1:
            raise ValueError("Impossible board: game should have ended after the game was won")
        return "win"
    if 'O' in winners:
        # O must have played last, so counts must be equal
        if count_x != count_o:
            raise ValueError("Impossible board: game should have ended after the game was won")
        return "win"

    # No winners: determine ongoing or draw
    if count_empty > 0:
        return "ongoing"
    return "draw"
